try{$q=db()->prepare('SELECT billing_name,company_name,address_line_1,address_line_2,city,state_province,postal_code,country,tax_id,vat_gst_number,billing_phone FROM user_billing_profiles WHERE user_id=? LIMIT 1');$q->execute([$uid]);$row=$q->fetch();if($row)$bp=array_merge($bp,$row);}catch(Throwable $e){}
