 verify_csrf(); $form=(string)post('form','personal');
 $name=trim((string)post('name'));$email=trim((string)post('email'));$timezone=trim((string)post('timezone','Asia/Kolkata'));$new=(string)post('password');
 $billingName=trim((string)post('billing_name'));$company=trim((string)post('company_name'));$a1=trim((string)post('address_line_1'));$a2=trim((string)post('address_line_2'));$city=trim((string)post('city'));$state=trim((string)post('state_province'));$postal=trim((string)post('postal_code'));$country=strtoupper(trim((string)post('country')));$tax=trim((string)post('tax_id'));$vat=trim((string)post('vat_gst_number'));$phone=trim((string)post('billing_phone'));
 if($form==='personal'){
   if($name===''||!valid_email($email)){flash('error','Please enter a valid name and email.');redirect('/settings/');}
   if($new!=='' && strlen($new)<10){flash('error','New password must be at least 10 characters.');redirect('/settings/');}
   db()->prepare('UPDATE users SET full_name=?,email=?,timezone=?,updated_at=NOW() WHERE id=?')->execute([$name,$email,$timezone,$uid]);
   if($new!=='')db()->prepare('UPDATE users SET password_hash=?,updated_at=NOW() WHERE id=?')->execute([password_hash($new,PASSWORD_DEFAULT),$uid]);
   flash('success','Your personal settings were saved.');redirect('/settings/');
 }
 if($billingName===''||$a1===''||$city===''||$state===''||$postal===''||!isset($countries[$country])){flash('error','Please complete Billing Name, Address, City, State/Province, Postal Code and Country.');redirect('/settings/');}
 foreach([['Billing Name',$billingName,180],['Company Name',$company,180],['Address Line 1',$a1,255],['Address Line 2',$a2,255],['City',$city,120],['State/Province',$state,120],['Postal Code',$postal,40],['Tax ID',$tax,120],['VAT/GST Number',$vat,120],['Billing Phone',$phone,40]] as $v)if(strlen($v[1])>$v[2]){flash('error',$v[0].' is too long.');redirect('/settings/');}
 try{
   db()->prepare('INSERT INTO user_billing_profiles(user_id,billing_name,company_name,address_line_1,address_line_2,city,state_province,postal_code,country,tax_id,vat_gst_number,billing_phone,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW()) ON DUPLICATE KEY UPDATE billing_name=VALUES(billing_name),company_name=VALUES(company_name),address_line_1=VALUES(address_line_1),address_line_2=VALUES(address_line_2),city=VALUES(city),state_province=VALUES(state_province),postal_code=VALUES(postal_code),country=VALUES(country),tax_id=VALUES(tax_id),vat_gst_number=VALUES(vat_gst_number),billing_phone=VALUES(billing_phone),updated_at=NOW()')->execute([$uid,$billingName,$company,$a1,$a2!==''?$a2:null,$city,$state,$postal,$country,$tax!==''?$tax:null,$vat!==''?$vat:null,$phone!==''?$phone:null]);
   flash('success','Billing information was saved.');redirect('/settings/');
 }catch(Throwable $e){flash('error','Could not save billing information. Please run the V15 database migration first, then try again.');redirect('/settings/');}
}
